import React, { useEffect, useState } from 'react';
import { useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import { FiEdit, FiChevronDown, FiChevronUp } from 'react-icons/fi';
import eventService from '../services/eventService';
import PastEventImageUpload from '../components/PastEventImageUpload';
import EventCard from '../components/EventCard';
import '../styles/Pages.css';
import { toast } from 'react-toastify';

const PastEvents = () => {
  const { user } = useContext(AuthContext);
  const [pastEvents, setPastEvents] = useState([]);
  const [userOwnedEvents, setUserOwnedEvents] = useState([]);
  const [loading, setLoading] = useState(false);
  const [expandedEvent, setExpandedEvent] = useState(null);
  const [editingEvent, setEditingEvent] = useState(null);
  const [eventDetails, setEventDetails] = useState({});

  useEffect(() => {
    fetchPastEvents();
  }, []);

  const fetchPastEvents = async () => {
    setLoading(true);
    try {
      const data = await eventService.getPastEvents();
      setPastEvents(data);
      
      // Filter events owned by current user
      if (user) {
        const owned = data.filter(event => event.organizer === user._id);
        setUserOwnedEvents(owned);
      }
    } catch (error) {
      toast.error('Error fetching past events');
      console.error('Error fetching past events:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleViewDetails = (eventId) => {
    window.location.href = `/event/${eventId}`;
  };

  const handleExpandEvent = (eventId) => {
    setExpandedEvent(expandedEvent === eventId ? null : eventId);
  };

  const handleUpdateEventDetails = async (eventId, updatedData) => {
    try {
      await eventService.updateEvent(eventId, updatedData);
      toast.success('Event details updated successfully!');
      setEditingEvent(null);
      fetchPastEvents();
    } catch (error) {
      toast.error('Failed to update event details');
    }
  };

  const handleImageRefresh = () => {
    fetchPastEvents();
  };

  return (
    <div className="past-events-page">
      <div className="page-header">
        <h1>Past Events</h1>
        <p>Relive amazing event memories and manage your galleries</p>
      </div>

      {loading ? (
        <div className="loading">Loading past events...</div>
      ) : (
        <>
          {/* User's Own Events Section */}
          {userOwnedEvents.length > 0 && (
            <div className="user-events-section">
              <h2>Your Past Events</h2>
              <p className="section-subtitle">Manage photos and details for your events</p>
              
              <div className="user-events-list">
                {userOwnedEvents.map(event => (
                  <div 
                    key={event._id}
                    className={`user-event-card ${expandedEvent === event._id ? 'expanded' : ''}`}
                  >
                    <div 
                      className="event-card-header"
                      onClick={() => handleExpandEvent(event._id)}
                    >
                      <div className="event-card-info">
                        <h3>{event.title}</h3>
                        <p className="event-meta">
                          {new Date(event.startDate).toLocaleDateString()} • {event.location}
                        </p>
                      </div>
                      <div className="expand-icon">
                        {expandedEvent === event._id ? (
                          <FiChevronUp size={24} />
                        ) : (
                          <FiChevronDown size={24} />
                        )}
                      </div>
                    </div>

                    {expandedEvent === event._id && (
                      <div className="event-card-content">
                        <PastEventImageUpload 
                          event={event}
                          onImageUploaded={handleImageRefresh}
                        />
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* All Past Events Section */}
          <div className="all-events-section">
            <h2>All Past Events</h2>
            {pastEvents.length > 0 ? (
              <div className="events-grid">
                {pastEvents.map(event => (
                  <EventCard
                    key={event._id}
                    event={event}
                    onViewDetails={handleViewDetails}
                  />
                ))}
              </div>
            ) : (
              <div className="no-events">
                <p>No past events yet</p>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default PastEvents;
